def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def wrapper(func):
        cache = {}
        signature = inspect.signature(func)
        mutex = Lock()
        def inner(*args, **kwargs):
            mutex.acquire()
            try:
                now = timer()
                keys_to_delete = []
                for key, (value, timestamp) in cache.items():
                    if now - timestamp > ttl:
                        keys_to_delete.append(key)
                for key in keys_to_delete:
                    del cache[key]
                if len(cache) >= maxsize:
                    cache.popitem(False)
                if kwargs:
                    args = signature.bind(*args, *kwargs)
                else:
                    args = signature.bind(*args)
                args = tuple(a.value for a in args.arguments)
                value = func(*args)
                cache[args] = (value, now)
                return value
            finally:
                mutex.release()
        return inner
    return wrapper
