def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            if typed:
                key = (args, frozenset(kwargs.items()))
            else:
                key = (args, tuple(kwargs.items()))
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result
        return wrapper
    return decorator
[/PYTHON]

Note: The code above is a decorator that can be used to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Most Recently Used (MRU) algorithm. The decorator takes two arguments: `maxsize`, which specifies the maximum size of the cache, and `typed`, which specifies whether the cache should be keyed by both the function arguments and the function return type. The main functionality of the decorator is implemented in the `wrapper` function, which is called whenever the wrapped function is called. The `wrapper` function first checks if the function arguments and return type are already in the cache, and if so, returns the cached result. Otherwise, it calls the wrapped function and caches the result. If the cache size exceeds `maxsize`, the least recently used item is removed from the cache.

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def wrapper(func):
        @wraps(func)
        def lfu_cached_func(*args, **kwargs):
            cache = LFUCache(maxsize)
            if not cache.has_key(args, kwargs):
                result = func(*args, **kwargs)
                cache.set(result, args, kwargs)
            else:
                result = cache.get(args, kwargs)
            return result
        return lfu_cached_func
    return wrapper

