def generate_diff_manifest(self, original_manifest, current_manifest):
    """Generate a diff manifest comparing the original and current manifests.

    Generate a diff manifest that compares the original manifest to the
    current manifest and returns a list of files that have changed.
    """
    # Check that the original manifest is a dictionary
    if not isinstance(original_manifest, dict):
        raise ValueError("Original manifest is not a dictionary")

    # Check that the current manifest is a dictionary
    if not isinstance(current_manifest, dict):
        raise ValueError("Current manifest is not a dictionary")

    # Check that the original and current manifests have the same structure
    if original_manifest.keys() != current_manifest.keys():
        raise ValueError("Original and current manifests have different structures")

    # Check that all files in the original manifest are present in the current manifest
    for file in original_manifest['files']:
        if not file in current_manifest['files']:
            raise ValueError(f"File '{file}' is not present in the current manifest")

    # Generate the diff manifest
    diff_manifest = []
    for file in original_manifest['files']:
        original_hash = original_manifest['files'][file]
        current_hash = current_manifest['files'][file]
        if original_hash != current_hash:
            diff_manifest.append({'file': file, 'original_hash': original_hash, 'current_hash': current_hash})

    return diff_manifest
