def load_configurations(config_filenames, overrides=None, resolve_env=True):
    configs = {}
    errors = []
    for config_filename in config_filenames:
        try:
            with open(config_filename) as f:
                config = yaml.safe_load(f)
                if overrides:
                    config = {**config, **overrides}
                if resolve_env:
                    config = {k: os.path.expandvars(v) for k, v in config.items()}
                configs[config_filename] = config
        except FileNotFoundError:
            errors.append(f"Configuration file not found: {config_filename}")
        except yaml.YAMLError as e:
            errors.append(f"Configuration file failed to parse: {config_filename}: {e}")
    return configs, errors
