def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): The dict containing the parsed spec.

    Returns:
        dict: The updated dict containing the included specs.
    """
    included_groups = {}
    for key, value in parser_dict.items():
        if isinstance(value, dict) and 'include' in value:
            included_groups[key] = self._include_groups(value)
        elif isinstance(value, list):
            included_groups[key] = self._include_groups_in_list(value)
    return included_groups

def _include_groups_in_list(self, include_list):
    included_groups_list = []
    for include_dict in include_list:
        included_groups_list.append(self._include_groups(include_dict))
